    const supabase = supabaseForUser(ctx);
    let query = supabase.from("crm_leads").select("id, firm, contact_name, email, phone, agency, stage, source, assigned_to, next_follow_up, do_not_contact, state, sector, need_score, created_at").order("created_at", { ascending: false }).limit(limit);
